// Mock CRM data (synthetic). Replace with an HTTP Request Tool or CRM node using a READ-ONLY credential.
const accounts = {
  'ACME-001': { name: 'Acme Corp (demo)', plan: 'Enterprise', owner_team: 'Team Blue', open_tickets: 2, monthly_fee_usd: 12000 },
  'GLOBEX-002': { name: 'Globex (demo)', plan: 'Business', owner_team: 'Team Green', open_tickets: 0, monthly_fee_usd: 3500 },
  'INITECH-003': { name: 'Initech (demo)', plan: 'Starter', owner_team: 'Team Red', open_tickets: 5, monthly_fee_usd: 800 }
};
const id = String(query || '').trim().toUpperCase().match(/[A-Z]+-\d+/);
if (!id || !accounts[id[0]]) return 'NOT_FOUND';
return JSON.stringify({ account_id: id[0], ...accounts[id[0]] });

// Mock status page (synthetic).
const status = {
  vpn: { status: 'degraded', note: 'Intermittent disconnects in EU region since 08:10 UTC (INC-4471)' },
  email: { status: 'operational', note: '' },
  crm: { status: 'operational', note: '' },
  billing: { status: 'maintenance', note: 'Planned maintenance 22:00-23:00 UTC' }
};
const key = String(query || '').toLowerCase().trim();
const match = Object.keys(status).find(k => key.includes(k));
if (!match) return 'NOT_FOUND. Valid services: ' + Object.keys(status).join(', ');
return JSON.stringify({ service: match, ...status[match] });

// Restricted tool: it never performs the action. It only records an approval request.
// In Lab 09 the request is sent to the approval workflow (Wait node + email).
const text = String(query || '');
const acct = (text.toUpperCase().match(/[A-Z]+-\d+/) || [null])[0];
const amount = Number((text.match(/\d+(?:\.\d+)?/g) || []).find(n => !acct || !acct.includes(n)) || NaN);
if (!acct || !(amount > 0)) return 'REJECTED: need an account ID and a positive amount.';
if (amount > 5000) return 'REJECTED: amount exceeds the 5000 USD policy cap for agent-initiated requests.';
const id = 'REQ-' + Date.now().toString().slice(-6);
return `PENDING_APPROVAL: request ${id} for ${amount} USD on ${acct} created. A human approver must approve it before anything happens.`;

// Turn the agent's intermediate steps into a JSON array of tool calls for logging.
const out = $input.first().json;
const steps = out.intermediateSteps || [];
const calls = steps.map(s => ({
  tool: s.action?.tool ?? 'unknown',
  input: s.action?.toolInput ?? null,
  output: String(s.observation ?? '').slice(0, 2000)
}));
let sessionId = 'unknown';
try { sessionId = $('Map Webhook Input').first().json.sessionId; } catch (e) {}
try { sessionId = $('When chat message received').first().json.sessionId || sessionId; } catch (e) {}
return [{ json: { answer: out.output, tool_calls: calls, tool_calls_json: JSON.stringify(calls), session_id: sessionId, execution_id: $execution.id } }];

